Процедура ОбработкаПроведения(Отказ, РежимПроведения)

	Если ПолучитьФункциональнуюОпцию("УчетЗарплатыИКадровВоВнешнейПрограмме") Тогда

		Оплаты = РаботникиОрганизации.Выгрузить();
		Отбор = Новый Структура();
		Отбор.Вставить("ВыплаченностьЗарплаты",Перечисления.ВыплаченностьЗарплаты.Задепонировано);
		Строки = Оплаты.НайтиСтроки(Отбор);
		Депоненты = Оплаты.Скопировать(Строки,"ФизЛицо, Сумма");

		Депоненты.Колонки.Добавить("ВидОперации", Новый ОписаниеТипов("ПеречислениеСсылка.ВидыОперацийПоЗарплате"));
		Депоненты.ЗаполнитьЗначения(Перечисления.ВидыОперацийПоЗарплате.Депонирование, "ВидОперации");
		Депоненты.Колонки.Добавить("СчетУчета", Новый ОписаниеТипов("ПланСчетовСсылка.Хозрасчетный"));
		Депоненты.ЗаполнитьЗначения(Планысчетов.Хозрасчетный.РасчетыПоДепонентам, "СчетУчета");
		Депоненты.Колонки["ФизЛицо"].Имя = "ФизическоеЛицо";

		ДанныеДляОтражения = Новый Структура;
		ДанныеДляОтражения.Вставить("Депоненты", Депоненты);
		УчетЗарплаты.СформироватьДвиженияПоОтражениюЗарплатыВРегламентированномУчете(Движения, Отказ, Организация, Дата, Дата, ДанныеДляОтражения);

	КонецЕсли;	

